import { Question } from "@/lib/types";

/**
 * Graduate Asymptotic Methods — § am2b
 * Optimal truncation: the least term
 * Topic group: Divergent Series & Optimal Truncation
 *
 * Locating the smallest term of a divergent asymptotic series, truncating one
 * term BEFORE it (the standard convention), and using the resulting partial sum
 * as a numerical estimate of the sum, with the smallest-term magnitude as an
 * error proxy.
 *
 * Seeded from Cambridge Part II Asymptotic Methods Example Sheet 1, esp.
 * Q9(c),(d) (Stieltjes integrals F, G) and Q10 (exponential integral E_1),
 * with constants/parameters varied. Recurring model series:
 *   E_1(x)   ~ e^{-x} \sum (-1)^n n!/x^{n+1}      term mag n!/x^{n+1}, n* ~ x
 *   F(x)     ~ \sum (-1)^n n! x^n                  term mag n! x^n,     n* ~ 1/x
 *   G(x)     ~ \sum (-1)^n (n+1)! x^n              term mag (n+1)! x^n, n* ~ 1/x
 *   erfc(x)  ~ (e^{-x^2}/(x\sqrt\pi)) \sum (-1)^n (2n-1)!!/(2x^2)^n,    n* ~ x^2
 *
 * All numerical estimates, smallest-term indices and reference values verified
 * with mpmath (quadrature for the integrals, mp.e1 for E_1, mp.erfc for erfc).
 */
